{"cards": [{"node_code": "N_c03f2afeb5a4cf01", "definition": "研究穿通型（PT）与非穿通型（NPT）IGBT的载流子存储机制、体区掺杂分布、开关特性及动态性能，涵盖两种结构在导通压降与关断损耗间的权衡。", "boundary": "聚焦于IGBT体区（N-漂移区）的掺杂与厚度设计对器件性能的影响。PT型强调少子存储以降低导通压降，NPT型强调少子寿命控制以优化开关速度。边界包括体区结构、少子寿命调控技术（如电子辐照）及两者在高频/低频应用中的对比。若内容侧重于表面栅极结构或反向导通特性，则不在此列。", "includes": ["PT与NPT IGBT的体区掺杂剖面与少子存储机制", "少子寿命控制工艺及其对开关损耗的影响", "PT/NPT结构在导通压降与开关速度上的性能对比"], "excludes": ["沟槽栅极结构的具体设计与制造（归入沟槽栅型IGBT）", "集成反并联二极管或反向导通沟道的结构（归入逆导型与逆阻型IGBT）"], "sibling_distinctions": [{"other_code": "N_4249d601f64c892e", "rule": "本节点关注体区掺杂与少子存储机制（纵向结构）；兄弟节点关注表面栅极几何形状与电流密度（横向结构）。"}, {"other_code": "N_56a6224938587041", "rule": "本节点关注正向阻断与导通特性；兄弟节点关注反向阻断能力或集成反并联二极管的结构。"}], "cross_boundary_rule": "若研究重点在于体区少子存储与寿命控制，归入本节点；若重点在于栅极几何优化，归入沟槽栅型IGBT；若重点在于反向特性，归入逆导/逆阻型IGBT。"}, {"node_code": "N_4249d601f64c892e", "definition": "研究采用沟槽栅极结构的IGBT，通过增加栅极周长与芯片面积比来提高电流密度，涵盖平面栅与沟槽栅的对比、短沟道效应及栅氧可靠性。", "boundary": "聚焦于IGBT表面栅极几何结构从平面（Planar）向沟槽（Trench）的演变。边界包括沟槽深度、宽度对阈值电压、导通电阻及短路耐受能力的影响，以及栅氧击穿风险与可靠性设计。若内容侧重于体区掺杂或反向导通特性，则不在此列。", "includes": ["沟槽栅极的几何参数设计与电流密度优化", "沟槽结构下的短沟道效应与栅极电荷分布", "沟槽栅IGBT的栅氧可靠性与短路耐受能力研究"], "excludes": ["体区少子存储机制与寿命控制（归入穿通型与非穿通型IGBT）", "集成反并联二极管或反向导通沟道的结构（归入逆导型与逆阻型IGBT）"], "sibling_distinctions": [{"other_code": "N_c03f2afeb5a4cf01", "rule": "本节点关注表面栅极几何形状与电流密度（横向结构）；兄弟节点关注体区掺杂与少子存储机制（纵向结构）。"}, {"other_code": "N_56a6224938587041", "rule": "本节点关注正向阻断与导通特性；兄弟节点关注反向阻断能力或集成反并联二极管的结构。"}], "cross_boundary_rule": "若研究重点在于栅极几何优化与电流密度提升，归入本节点；若重点在于体区少子存储，归入穿通/非穿通型IGBT；若重点在于反向特性，归入逆导/逆阻型IGBT。"}, {"node_code": "N_56a6224938587041", "definition": "研究具有反向阻断能力（RBS）或集成反并联二极管（RC）的IGBT结构，涵盖反向导通沟道设计、体二极管特性及在单管拓扑中的应用优势。", "boundary": "聚焦于IGBT在反向电压下的行为及与体二极管的集成。边界包括逆阻型（RBS-IGBT）的P+集电极结构、逆导型（RC-IGBT）的集成二极管设计、反向恢复特性及在共源共栅等拓扑中的替代优势。若内容侧重于正向导通压降或栅极结构，则不在此列。", "includes": ["逆阻型（RBS）IGBT的P+集电极结构与反向阻断机制", "逆导型（RC）IGBT的集成体二极管设计与反向恢复特性", "RC/RBS IGBT在简化功率模块拓扑中的应用"], "excludes": ["纯正向导通压降优化与体区少子存储（归入穿通型与非穿通型IGBT）", "纯栅极几何形状优化（归入沟槽栅型IGBT）"], "sibling_distinctions": [{"other_code": "N_c03f2afeb5a4cf01", "rule": "本节点关注反向阻断能力或集成反并联二极管的结构；兄弟节点关注正向阻断与导通特性。"}, {"other_code": "N_4249d601f64c892e", "rule": "本节点关注反向阻断能力或集成反并联二极管的结构；兄弟节点关注表面栅极几何形状与电流密度。"}], "cross_boundary_rule": "若研究重点在于反向阻断能力或集成反并联二极管，归入本节点；若重点在于正向体区或栅极结构，归入相应兄弟节点。"}]}
